<?php use App\Models\Content;use App\Services\Navigation;use App\Core\DB;
$items=Content::published('section_items','section_id=?',[$section['id']],(int)$section['display_limit']);$type=$section['section_type'];
$buttons=static function(array $row):void{if(!empty($row['button_label'])&&!empty($row['button_url']))echo '<a class="gtl-btn gtl-btn-primary" href="'.e(cms_url($row['button_url'])).'">'.e($row['button_label']).'</a>';if(!empty($row['secondary_label'])&&!empty($row['secondary_url']))echo '<a class="gtl-btn" href="'.e(cms_url($row['secondary_url'])).'">'.e($row['secondary_label']).'</a>';};
?>
<?php if($type==='hero'):$slides=Content::published('hero_slides','section_id=?',[$section['id']]);if(!$slides)return;?>
<section class="gtl-hero"><div class="gtl-hero-stage" data-gtl-hero data-autoplay="<?=(int)$section['autoplay']?>"><?php foreach($slides as $index=>$slide):?><article class="gtl-hero-slide <?=$index===0?'active':''?> cms-align-<?=e($slide['alignment'])?>" data-duration="<?=(int)$slide['duration']?>"><div class="gtl-hero-media" aria-label="<?=e($slide['title'])?>"><?php $video=media_url($slide['video_id'])?:$slide['video_url'];if($video):?><video autoplay muted loop playsinline preload="metadata" poster="<?=e(media_url($slide['poster_id']?:$slide['image_id']))?>"><source src="<?=e(cms_url($video))?>"></video><?php elseif($slide['image_id']):?><?=media_img($slide['image_id'],$slide['title'],'',false)?><?php elseif(!empty($slide['external_image_url'])):?><img src="<?=e(cms_url($slide['external_image_url']))?>" alt="<?=e($slide['title'])?>"><?php endif?></div><div class="gtl-hero-overlay" style="display:block;background:rgba(0,0,0,<?=((int)$slide['overlay_opacity'])/100?>)"></div><div class="gtl-container gtl-hero-grid gtl-hero-grid-bottom"><div class="gtl-hero-copy"><div class="gtl-hero-text"><?php if($slide['eyebrow']):?><div class="gtl-eyebrow"><?=e($slide['eyebrow'])?></div><?php endif?><h1><?=e($slide['title'])?> <span><?=e($slide['highlight'])?></span></h1><?php if($slide['subtitle']):?><h2><?=e($slide['subtitle'])?></h2><?php endif?><p><?=e($slide['description'])?></p></div><div class="gtl-actions"><?php $buttons($slide);?></div></div></div></article><?php endforeach?><?php if(count($slides)>1):?><div class="gtl-hero-indicators" aria-label="Hero slides"><?php foreach($slides as $index=>$slide):?><button type="button" class="<?=$index===0?'active':''?>" data-gtl-slide="<?=$index?>" aria-label="<?=e($slide['title'])?>"></button><?php endforeach?></div><?php endif?></div></section>
<?php elseif($type==='brands'):$brands=$section['content_mode']==='automatic'?Content::published('brands','1=1',[],(int)$section['display_limit']):array_filter(array_map(fn($i)=>$i['brand_id']?Content::find('brands',(int)$i['brand_id']):null,$items),fn($b)=>$b&&Content::isLive($b,'brands'));?>
<section class="gtl-brands reveal" id="brands-<?=$section['id']?>"><div class="gtl-container"><div class="gtl-brand-header"><span class="gtl-brand-kicker"><?=e($section['eyebrow'])?></span><h2 class="gtl-brand-title"><?=e($section['heading'])?></h2><p class="gtl-brand-subtitle"><?=e($section['description'])?></p></div><div class="gtl-brand-viewport" data-speed="<?=(int)$section['slider_speed']?>"><div class="gtl-brand-slider"><?php for($copy=0;$copy<2;$copy++):?><div class="gtl-brand-set" <?=$copy?'aria-hidden="true"':''?>><?php foreach($brands as $brand):?><a href="<?=e(cms_url(Navigation::recordUrl('brands',$brand)))?>" class="gtl-brand-card <?=$brand['image_id']?'':'gtl-brand-card-text'?>" <?=$copy?'tabindex="-1"':''?>><?=$brand['image_id']?media_img($brand['image_id'],$brand['title']):e($brand['title'])?></a><?php endforeach?></div><?php endfor?></div></div></div></section>
<?php elseif($type==='categories'):$cards=$section['content_mode']==='automatic'?array_map(fn($c)=>$c+['button_url'=>Navigation::recordUrl('categories',$c),'button_label'=>setting('text.learn_more')],Content::published('categories','1=1',[],(int)$section['display_limit'])):$items;?>
<section class="gtl-solutions" id="products-<?=$section['id']?>"><div class="gtl-solutions-bg" aria-hidden="true"><span class="gtl-blob gtl-blob-1"></span><span class="gtl-blob gtl-blob-2"></span><span class="gtl-blob gtl-blob-3"></span><span class="gtl-mesh"></span></div><div class="gtl-container"><div class="gtl-section-head reveal"><div class="gtl-eyebrow"><?=e($section['eyebrow'])?></div><h2><?=e($section['heading'])?></h2><p><?=e($section['description'])?></p></div><div class="gtl-solutions-scroller"><div class="gtl-solutions-grid"><?php foreach($cards as $index=>$card):?><a class="gtl-solution-card reveal" href="<?=e(cms_url($card['button_url']?:($card['category_id']??null?Navigation::recordUrl('categories',Content::find('categories',(int)$card['category_id'])):'#')))?>" data-index="<?=$index?>"><span class="gtl-card-accent" aria-hidden="true"></span><span class="gtl-card-glow" aria-hidden="true"></span><span class="gtl-card-shine" aria-hidden="true"></span><div class="gtl-card-image-wrap"><?php if($card['image_id']):?><?=media_img($card['image_id'],$card['title'])?><?php else:?><div class="gtl-card-image-placeholder"><i class="<?=e($card['icon']?:'fa-solid fa-box')?>"></i></div><?php endif?></div><h3><?=nl2br(e($card['title']))?></h3><p class="gtl-card-desc"><?=e($card['description'])?></p><span class="gtl-card-cta"><?=e($card['button_label']?:setting('text.learn_more'))?> <i class="fa-solid fa-arrow-right"></i></span></a><?php endforeach?></div></div></div></section>
<?php elseif($type==='about'):?>
<section class="about gtl-about"><div class="gtl-container"><div class="gtl-about-grid"><div class="gtl-about-copy reveal"><div class="gtl-eyebrow"><?=e($section['eyebrow'])?></div><h2><?=e($section['heading'])?><span><?=e($section['highlight'])?></span></h2><p><?=e($section['description'])?></p><div class="rich-text"><?=rich($section['body'])?></div><?php $buttons($section);?><div class="gtl-about-trust"><?php foreach($items as $item):?><div class="gtl-trust-mark"><i class="<?=e($item['icon'])?>"></i><span><?=e($item['title'])?></span></div><?php endforeach?></div></div><div class="gtl-about-media"><div class="gtl-about-images reveal"><div class="gtl-images-grid"><?=media_img($section['image_id'],$section['heading'],'gtl-about-img gtl-about-img-main')?><?=media_img($section['secondary_image_id'],$section['heading'],'gtl-about-img gtl-about-img-secondary')?></div></div></div></div></div></section>
<?php elseif($type==='stats'):?>
<section class="gtl-stats-section"><div class="gtl-container"><div class="gtl-stats reveal"><?php foreach($items as $item):$value=$item['stat_value'];if(in_array($item['stat_source'],['products','brands','categories'],true))$value=DB::value('SELECT COUNT(*) FROM `'.$item['stat_source'].'` WHERE '.Content::liveWhere($item['stat_source']));elseif($item['stat_source']==='years')$value=max(0,(int)gmdate('Y')-(int)setting('founded_year','1999'));?><div class="gtl-stat"><div class="gtl-stat-icon"><i class="<?=e($item['icon'])?>"></i></div><div><strong data-count="<?=(int)$value?>" data-prefix="<?=e($item['prefix'])?>" data-suffix="<?=e($item['suffix'])?>"><?=e($item['prefix'].number_format((int)$value).$item['suffix'])?></strong><span><?=e($item['title'])?></span></div></div><?php endforeach?></div></div></section>
<?php elseif($type==='features'):$featureHeading=$section['heading'];$featureItems=$items;if(!$featureItems)foreach(array_filter([(int)$section['image_id'],(int)$section['secondary_image_id']]) as $imageId)$featureItems[]=['title'=>$featureHeading,'description'=>$section['description'],'image_id'=>$imageId,'icon'=>'','button_label'=>$section['button_label'],'button_url'=>$section['button_url'],'secondary_label'=>$section['secondary_label'],'secondary_url'=>$section['secondary_url']];?><section class="benefits" id="features-<?=$section['id']?>"><div class="gtl-container"><?php if($featureHeading||$section['eyebrow']||$section['description']||$section['body']):?><div class="gtl-section-head reveal"><?php if($section['eyebrow']):?><div class="gtl-eyebrow"><?=e($section['eyebrow'])?></div><?php endif?><?php if($featureHeading):?><h2><?=e($featureHeading)?></h2><?php endif?><?php if($section['description']):?><p><?=e($section['description'])?></p><?php endif?><?php if($section['body']):?><div class="rich-text"><?=rich($section['body'])?></div><?php endif?></div><?php endif?><div class="benefits-grid"><?php foreach($featureItems as $item):?><article class="benefit"><div class="benefit-media"><?php if($item['image_id']):?><?=media_img($item['image_id'],$item['title'],'benefit-image')?><?php else:?><span class="benefit-icon"><i class="<?=e($item['icon'])?>"></i></span><?php endif?></div><div class="benefit-content"><h4><?=e($item['title'])?></h4><p><?=e($item['description'])?></p><?php $buttons($item);?></div></article><?php endforeach?></div></div></section>
<?php elseif($type==='cta'):?><section class="cta-section" <?php if($section['image_id']):?>style="background-image:linear-gradient(#003d2877,#003d2877),cms_url('<?=e(media_url($section['image_id']))?>');background-size:cover"<?php endif?>><div class="container"><h2><?=e($section['heading'])?></h2><p><?=e($section['description'])?></p><div class="gtl-actions"><?php $buttons($section);?></div></div></section>
<?php elseif($type==='testimonials'):?><section class="section-padding"><div class="container"><h2><?=e($section['heading'])?></h2><div class="row g-4"><?php foreach($items as $item):?><div class="col-md-4 reveal"><div class="testimonial-card"><p>“<?=e($item['description'])?>”</p><div class="testi-author"><?=media_img($item['image_id'],$item['title'])?><div><h5><?=e($item['title'])?></h5><div><?=rich($item['body'])?></div></div></div></div></div><?php endforeach?></div></div></section>
<?php elseif($type==='contact'):view('public/contact-form',['section'=>$section,'form_errors'=>session('enquiry_errors',[]),'form_values'=>request()->query()]);?>
<?php else:?><section class="section-padding"><div class="container"><span class="section-kicker"><?=e($section['eyebrow'])?></span><h2 class="section-title"><?=e($section['heading'])?></h2><p><?=e($section['description'])?></p><div class="rich-text"><?=rich($section['body'])?></div><?php $buttons($section);?></div></section><?php endif?>
